// Copies the Simple Icons logos used in lib/link-icons.tsx into lib/brand-icons.generated.ts.
// The simple-icons entry file is ~5 MB and breaks Turbopack's production build, so the app
// imports this small generated file instead. Run after adding a `brand(siX)` entry:
//   npm run icons:brands
import { readFileSync, writeFileSync } from "node:fs";
import * as simpleIcons from "simple-icons";

const registry = new URL("../lib/link-icons.tsx", import.meta.url);
const output = new URL("../lib/brand-icons.generated.ts", import.meta.url);

const names = [...new Set([...readFileSync(registry, "utf8").matchAll(/brand\((si\w+)\)/g)].map((m) => m[1]))].sort();

const missing = names.filter((name) => !simpleIcons[name]);
if (missing.length) {
  console.error(`Not in simple-icons: ${missing.join(", ")}`);
  process.exit(1);
}

const lines = names.map((name) => {
  const { title, hex, path } = simpleIcons[name];
  return `export const ${name}: BrandIconData = ${JSON.stringify({ title, hex, path })};`;
});

writeFileSync(
  output,
  `// Generated by scripts/generate-brand-icons.mjs from simple-icons (CC0-1.0). Do not edit.\n` +
    `export type BrandIconData = { title: string; hex: string; path: string };\n\n` +
    `${lines.join("\n")}\n`
);
console.log(`Wrote ${names.length} brand icons to lib/brand-icons.generated.ts`);
